CREATE OR REPLACE FUNCTION public.fn_pnl_evidence_cents(p_value jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v numeric;
BEGIN
 IF jsonb_typeof(p_value) IS DISTINCT FROM 'number' THEN RETURN NULL; END IF;
 v := (p_value#>>'{}')::numeric;
 IF v::text IN ('NaN','Infinity','-Infinity') OR v<>round(v,2) THEN RETURN NULL; END IF;
 RETURN v;
EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_original_frame()
 RETURNS union_pnl_transaction_frames
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE frame public.union_pnl_transaction_frames; observed timestamptz; book timestamptz;
BEGIN
 SELECT * INTO frame FROM public.union_pnl_transaction_frames WHERE transaction_id=pg_current_xact_id();
 IF FOUND THEN RETURN frame; END IF;
 observed:=clock_timestamp(); book:=public.fn_union_week_start(observed);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
 observed:=clock_timestamp();
 IF public.fn_union_week_start(observed)<>book THEN
  book:=public.fn_union_week_start(observed);
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  observed:=clock_timestamp();
  IF public.fn_union_week_start(observed)<>book THEN RAISE EXCEPTION 'pnl_frame_clock_crossed_twice' USING ERRCODE='40001'; END IF;
 END IF;
 INSERT INTO public.union_pnl_transaction_frames VALUES(pg_current_xact_id(),observed,book) RETURNING * INTO frame;
 RETURN frame;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.horse_cash_retained_request_matches(p_table uuid, p_number bigint, p_hash text, p_request jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE c smarter_private.horse_cash_payload_certificates; p public.cash_hand_provenance_receipts; retained smarter_private.horse_cash_postprune_certificates;
BEGIN
 SELECT * INTO c FROM smarter_private.horse_cash_payload_certificates WHERE table_id=p_table AND hand_number=p_number;
 IF NOT FOUND THEN
  SELECT * INTO retained FROM smarter_private.horse_cash_postprune_certificates WHERE table_id=p_table AND hand_number=p_number;
  IF NOT FOUND THEN RETURN encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex') IS NOT DISTINCT FROM p_hash; END IF;
  SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=p_table AND hand_number=p_number;
  RETURN FOUND AND (p.hand_id,p.manifest_id,p.accepted_at,p.payload_hash) IS NOT DISTINCT FROM
   (retained.hand_id,retained.manifest_id,retained.accepted_at,retained.original_request_sha256)
   AND p_hash=retained.original_request_sha256 AND p.accepted_request IS NOT DISTINCT FROM p_request
   AND encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex')=retained.compact_request_sha256
   AND encode(extensions.digest(convert_to(p.atomic_receipt::text,'UTF8'),'sha256'),'hex')=retained.compact_atomic_sha256
   AND encode(extensions.digest(convert_to((to_jsonb(p)-ARRAY['accepted_request','atomic_receipt','accepted_at'])::text,'UTF8'),'sha256'),'hex')=retained.immutable_financial_sha256;
 END IF;
 SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=p_table AND hand_number=p_number;
 RETURN FOUND AND p.hand_id=c.hand_id AND p.manifest_id=c.manifest_id AND p.accepted_at=c.accepted_at
 AND p_hash=c.original_request_sha256 AND p.payload_hash=p_hash
 AND p.accepted_request IS NOT DISTINCT FROM p_request
 AND encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex')=c.compact_request_sha256
 AND encode(extensions.digest(convert_to(p.atomic_receipt::text,'UTF8'),'sha256'),'hex')=c.compact_atomic_sha256
 AND encode(extensions.digest(convert_to((to_jsonb(p)-ARRAY['accepted_request','atomic_receipt','accepted_at'])::text,'UTF8'),'sha256'),'hex')=c.immutable_financial_sha256;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.horse_cash_retained_atomic_matches(p_table uuid, p_number bigint, p_original jsonb, p_live jsonb, p_request jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE c smarter_private.horse_cash_payload_certificates;
BEGIN
 IF EXISTS(SELECT 1 FROM smarter_private.horse_cash_postprune_certificates WHERE table_id=p_table AND hand_number=p_number) THEN RETURN false; END IF;
 SELECT * INTO c FROM smarter_private.horse_cash_payload_certificates WHERE table_id=p_table AND hand_number=p_number;
 IF NOT FOUND THEN RETURN public.fn_cash_atomic_original_matches(p_original,p_live,p_request); END IF;
 RETURN smarter_private.horse_cash_retained_request_matches(p_table,p_number,c.original_request_sha256,p_request)
 AND encode(extensions.digest(convert_to(p_original::text,'UTF8'),'sha256'),'hex')=c.compact_atomic_sha256
 AND encode(extensions.digest(convert_to(p_live::text,'UTF8'),'sha256'),'hex')=c.live_atomic_sha256;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_capture_accepted_cash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE frame public.union_pnl_transaction_frames; p public.cash_hand_provenance_receipts; scope jsonb; proof jsonb;
BEGIN
 -- DIAMOND PHASE 9, STEP 0: the Diamond Arena is in no union and a Diamond hand
 -- is not a chip cash outcome.
 IF EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
             WHERE t.id=NEW.table_id AND c.asset='diamonds') THEN RETURN NULL; END IF;
 frame:=public.fn_union_pnl_original_frame();
 SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number;
 IF p.table_id IS NOT NULL THEN
  scope:=p.game_scope;
  IF p.hand_id IS DISTINCT FROM NEW.hand_id OR p.payload_hash IS DISTINCT FROM NEW.payload_hash OR p.transaction_id IS DISTINCT FROM frame.transaction_id THEN
   proof:=jsonb_build_object('status','blocked','basis_certified',false,'reason','accepted_cash_original_identity_mismatch');
  ELSE
   proof:=public.fn_pnl_cash_hand_evidence(NEW.table_id,NEW.hand_number)||jsonb_build_object('accepted_rake',p.rake,'accepted_bbj',p.bbj,'accepted_external_net',p.signed_external_net);
  END IF;
 ELSE
  SELECT jsonb_build_object('host_club_id',club_id,'game_union_id',union_id,'is_private',is_private,'tournament_id',tournament_id,'asset','chips','unit_scale',2)
  INTO scope FROM public.tables WHERE id=NEW.table_id;
  IF scope->'tournament_id' IS DISTINCT FROM 'null'::jsonb AND scope->>'tournament_id' IS NOT NULL THEN RETURN NULL; END IF;
  proof:=jsonb_build_object('status','blocked','basis_certified',false,'reason','accepted_cash_original_provenance_missing');
 END IF;
 INSERT INTO public.union_pnl_cash_outcomes VALUES(NEW.table_id,NEW.hand_number,NEW.hand_id,frame.transaction_id,
  frame.observed_at,NEW.payload_hash,COALESCE(scope,'{}'),proof);
 RETURN NULL;
END $function$
